/* the book's numbers, computed once (chapter 3.5 and 3.6 worked examples) */
const OQ_h=6.63e-34, OQ_m0=9.11e-31, OQ_q=1.602e-19, OQ_Lw=1e-8;
const OQ_E1=(m,L)=>OQ_h*OQ_h/(8*m*L*L)/OQ_q;                 // infinite-well level in eV
const OQ_E1e=OQ_E1(0.067*OQ_m0,OQ_Lw);                       // 0.0562 eV
const OQ_E1h=OQ_E1(0.50*OQ_m0,OQ_Lw);                        // 0.0075 eV
const OQ_E1free=OQ_E1(OQ_m0,OQ_Lw);                          // 0.0038 eV (the m0 trap)
