const OQ_TW=OQ_D(Math.asin(Math.sqrt(0.20)));                // 26.57°: the cone that would hold a fraction 0.20
/* a Lambertian source at (x,y) facing right: its polar pattern (a circle through the source) and a cone of half-angle th */
const OQ_lamb=(x,y,R,th,col,L)=>{const dx=L*Math.cos(OQ_R(th)),dy=L*Math.sin(OQ_R(th));
 return `<circle cx="${x+R}" cy="${y}" r="${R}" fill="#FFF4E6" stroke="${ORG}" stroke-width="3"/>`+
 `<polygon points="${x},${y} ${(x+dx).toFixed(1)},${(y-dy).toFixed(1)} ${(x+dx).toFixed(1)},${(y+dy).toFixed(1)}" fill="${col}" fill-opacity=".22" stroke="${col}" stroke-width="3"/>`+
 `<rect x="${x-16}" y="${y-34}" width="16" height="68" rx="3" fill="${ORG}"/>`};
/* a band diagram: well from xa to xb, cladding conduction edge yc0, well conduction edge yc1, well valence edge yv1, cladding valence edge yv0 */
